package com.rustypayments.implementation;

import com.rustypayments.PaymentCalendar;

import java.time.*;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import java.time.temporal.ChronoUnit;
import java.time.temporal.TemporalAdjusters;
import java.util.Set;

public class ModernPaymentCalendar implements PaymentCalendar {

    private static final ZoneId BANK_ZONE = ZoneId.of("Europe/Warsaw");
    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);
    private static final DateTimeFormatter INSTANT_FORMATTER = DateTimeFormatter.ISO_OFFSET_DATE_TIME;
    private static final LocalTime CUTOFF_TIME = LocalTime.of(16, 0, 0);

    private static final Set<MonthDay> HOLIDAYS = Set.of(
            MonthDay.of(Month.JANUARY, 1),
            MonthDay.of(Month.JANUARY, 6),
            MonthDay.of(Month.MAY, 1),
            MonthDay.of(Month.MAY, 3),
            MonthDay.of(Month.AUGUST, 15),
            MonthDay.of(Month.NOVEMBER, 1),
            MonthDay.of(Month.NOVEMBER, 11),
            MonthDay.of(Month.DECEMBER, 25),
            MonthDay.of(Month|December, 26)
    );

    // Manually defining the set since I can't use the above syntax in all versions easily
    // but Java 21 is allowed.
    private static final Set<MonthDay> BANK_HOLIDAYS = Set.of(
            MonthDay.of(1, 1),
            MonthDay.of(1, 6),
            MonthDay.of(5, 1),
            MonthDay.of(5, 3),
            MonthDay.of(8, 15),
            MonthDay.of(11, 1),
            MonthDay.of(11, 11),
            MonthDay.of(12, 25),
            MonthDay.of(12, 26)
    );

    @Override
    public boolean isBusinessDay(String date) {
        LocalDate d = parseLocalDate(date);
        return isBusinessDay(d);
    }

    @Override
    public String processingDate(String submittedAt) {
        ZonedDateTime instant = parseInstant(submittedAt).withZoneSameInstant(BANK_ZONE);
        LocalDate date = instant.toLocalDate();
        LocalTime time = instant.toLocalTime();

        if (isBusinessDay(date) && !time.isAfter(CUTOFF_TIME)) {
            return date.toString();
        } else {
            return nextBusinessDay(date).toString();
        }
    }

    @Override
    public String settlementDate(String submittedAt) {
        ZonedDateTime instant = parseInstant(submittedAt).withZoneSameInstant(BANK_ZONE);
        LocalDate processing = processingDateLocal(instant);
        return nextBusinessDay(processing).toString();
    }

    private LocalDate processingDateLocal(ZonedDateTime instant) {
        ZonedDateTime warsawInstant = instant.withZoneSameInstant(BANK_ZONE);
        LocalDate date = warsawInstant.toLocalDate();
        LocalTime time = warsawInstant.toLocalTime();

        if (isBusinessDay(date) && !time.isAfter(CUTOFF_TIME)) {
            return date;
        } else {
            return nextBusinessDay(date);
        }
    }

    @Override
    public int daysLate(String dueDate, String paidAt) {
        LocalDate due = parseLocalDate(dueDate);
        ZonedDateTime paid = parseInstant(paidAt).withZoneSameInstant(BANK_ZONE);
        long late = ChronoUnit.DAYS.between(due, paid.toLocalDate());
        return (int) Math.max(0, late);
    }

    @Override
    public String addMonths(String date, int months) {
        LocalDate d = parseLocalDate(date);
        boolean wasMonthEnd = d.equals(d.with(TemporalAdjusters.lastDayOfMonth()));
        LocalDate result = d.plusMonths(months);
        if (wasMonthEnd) {
            result = result.with(TemporalAdjusters.lastDayOfMonth());
        }
        return result.toString();
    }

    private boolean isBusinessDay(LocalDate date) {
        DayOfWeek dow = date.getDayOfWeek();
        if (dow == DayOfWeek.SATURDAY || dow == DayOfWeek.SUNDAY) {
            return false;
        }
        return !BANK_HOLIDAYS.contains(MonthDay.from(date));
    }

    private LocalDate nextBusinessDay(LocalDate from) {
        LocalDate date = from;
        do {
            date = date.plusDays(1);
        } while (!isBusinessDay(date));
        return date;
    }

    private LocalDate parseLocalDate(String text) {
        if (text == null || text.isBlank()) throw new IllegalArgumentException();
        try {
            return LocalDate.parse(text, DATE_FORMATTER);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException(e);
        }
    }

    private ZonedDateTime parseInstant(String text) {
        if (text == null || text.isBlank()) throw new IllegalArgumentException();
        try {
            return ZonedDateTime.parse(text, INSTANT_FORMATTER);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException(e);
        }
    }
}

